// 创建/加入沿真实到达和同界名册；工程/会战/本人确认均绑定原唯一Common前序，拒无源增删参与者。
#include "military_siege_lifecycle_history.hpp"
#include "military_field_command_source.hpp"
#include <algorithm>
#include <charconv>
#include <limits>
#include <map>
#include <set>
namespace hanmo::resident {
namespace {
template<class T>const T* find(const std::vector<T>& rows,const StableId& id){for(const auto& x:rows)if(x.id==id)return &x;return nullptr;}
bool same(const MilitarySiegeParticipationSnapshot& a,const MilitarySiegeParticipationSnapshot& b){return a.phase==b.phase&&a.started_tick==b.started_tick&&a.last_tick==b.last_tick&&a.round==b.round&&a.armies==b.armies&&a.unit_nodes==b.unit_nodes&&a.withdrawn_army_ids==b.withdrawn_army_ids;}
std::optional<std::size_t> position(const CommonStore& c,const StableId& id){const auto& order=c.state().facts.order();auto it=std::find(order.begin(),order.end(),id);return it==order.end()?std::nullopt:std::optional<std::size_t>{std::size_t(it-order.begin())};}
bool canonical(const CommonStore& c,const StableId& id){const StableId prefix="military_siege_lifecycle:";if(id.rfind(prefix,0)!=0)return false;Integer n=0;auto text=id.substr(prefix.size());auto p=std::from_chars(text.data(),text.data()+text.size(),n);return p.ec==std::errc{}&&p.ptr==text.data()+text.size()&&n>0&&n<c.state().next_instance_id&&std::to_string(n)==text;}
Outcome<Integer> limit(const CommonStore& c,const DynamicStepInput* p){if(!p)return {true,c.tick(),{}};if(p->from_tick<0||p->from_tick!=c.tick()||p->from_tick==std::numeric_limits<Integer>::max()||p->to_tick!=p->from_tick+1)return {false,{},common_failure("MilitarySiegeLifecyclePhaseMismatch").error};return {true,p->to_tick,{}};}
bool selected(const MilitarySiegeEngineeringPolicy& p,const StableId& id){return std::find(p.topology_ids.begin(),p.topology_ids.end(),id)!=p.topology_ids.end();}
Status cause(const CommonStore& c,const MilitarySiegeLifecycleFact& f,const StableId& kind){const auto* h=c.state().facts.find(f.cause_id);auto at=position(c,f.id),prior=position(c,f.cause_id);return h&&h->id==f.cause_id&&h->kind==kind&&h->domain=="military"&&at&&prior&&*prior<*at?common_success():common_failure("MilitarySiegeLifecycleCauseRequired",f.id);}
Status actual_army_actor(const CommonStore& c,const MilitaryState& m,const StableId& army,const MilitarySiegeLifecycleFact& f){auto source=query_military_army_command_source_before(c,m,army,f.id);return !source.ok?Status{false,{},source.error}:source.value.commander_actor_id==f.actor_id?common_success():common_failure("MilitarySiegeLifecycleAuthorityRequired",f.id);}
}
Status validate_military_siege_participation_history(const CommonStore& c,const MilitaryState& m,const MilitaryCatalog& cat,const MilitarySiegeEngineeringPolicy& policy,const MilitarySiegeLifecycleState& state,const MilitarySiegeEngineeringState& engineering,const DynamicStepInput* phase,const PopulationMilitaryState* population,const PopulationMilitaryCatalog* population_catalog){
 auto upper=limit(c,phase);if(!upper.ok)return {false,{},upper.error};auto checked=validate_military_siege_engineering_rule(policy.rule);if(!checked.ok)return checked;std::map<StableId,const MilitarySiegeLifecycleFact*> latest;std::set<StableId> ids;std::optional<std::size_t> previous_order;Integer previous_tick=-1;
 std::set<StableId> topologies;if(policy.topology_ids.empty()||policy.topology_ids.size()>64)return common_failure("MilitarySiegeEngineeringTopologyRequired");for(const auto& id:policy.topology_ids)if(!find(cat.siege_topologies,id)||!topologies.insert(id).second)return common_failure("MilitarySiegeEngineeringTopologyRequired",id);
 std::vector<StableId> all_units;for(const auto& camp:cat.garrisons)for(const auto& u:camp.units)all_units.push_back(u.id);
 for(const auto& f:state.facts){const auto* siege=find(m.sieges,f.siege_id);const auto* topology=find(cat.siege_topologies,f.topology_id);const auto* head=c.state().facts.find(f.id);auto at=position(c,f.id);
  if(!siege||!topology||siege->topology_id!=f.topology_id||!selected(policy,f.topology_id)||!canonical(c,f.id)||!head||head->id!=f.id||head->kind!=military_siege_lifecycle_kind_name(f.kind)||head->domain!="military"||!at||(previous_order&&*at<=*previous_order)||!ids.insert(f.id).second||f.tick>upper.value||f.tick<previous_tick)return common_failure("MilitarySiegeLifecycleFactMismatch",f.id);previous_order=at;previous_tick=f.tick;checked=validate_military_siege_lifecycle_shape(f,*topology);if(!checked.ok)return checked;
  auto previous=latest.find(f.siege_id);if(previous==latest.end()){if(f.kind!=MilitarySiegeLifecycleKind::created)return common_failure("MilitarySiegeParticipationCreationMissing",f.id);}else if(!f.before||f.previous_fact_id!=previous->second->id||!same(*f.before,previous->second->after)||f.tick<previous->second->tick)return common_failure("MilitarySiegeParticipationHistoryMismatch",f.id);
  if(f.kind==MilitarySiegeLifecycleKind::created||f.kind==MilitarySiegeLifecycleKind::joined){
   checked=cause(c,f,"campaign_arrival");if(!checked.ok)return checked;const auto* arrival=find(m.arrival_facts,f.cause_id);if(!arrival||arrival->tick>f.tick||arrival->actor_id!=f.actor_id||arrival->stronghold_id!=siege->stronghold_id)return common_failure("MilitarySiegeLifecycleArrivalMismatch",f.id);checked=actual_army_actor(c,m,arrival->army_id,f);if(!checked.ok)return checked;
   std::vector<std::pair<StableId,Integer>> added;for(const auto& army:f.after.armies)if(!f.before||std::find(f.before->armies.begin(),f.before->armies.end(),army)==f.before->armies.end())added.push_back(army);
   if(f.kind==MilitarySiegeLifecycleKind::created){if(arrival->campaign_id!=siege->campaign_id||std::count(added.begin(),added.end(),std::make_pair(arrival->army_id,Integer(0)))!=1||std::count_if(added.begin(),added.end(),[](const auto& a){return a.second==0;})!=1)return common_failure("MilitarySiegeLifecycleArrivalMismatch",f.id);}else if(added.size()!=1||added.front().first!=arrival->army_id)return common_failure("MilitarySiegeLifecycleArrivalMismatch",f.id);
   auto roster=phase?military_rosters_before(c,m,cat,all_units,f.tick,f.id,*phase,population,population_catalog):military_rosters_before(c,m,cat,all_units,f.tick,f.id,population,population_catalog);if(!roster.ok)return {false,{},roster.error};std::vector<std::pair<StableId,StableId>> expected=f.before?f.before->unit_nodes:std::vector<std::pair<StableId,StableId>>{};
   for(const auto& army:added){bool any=false;for(const auto& unit:roster.value)if(unit.army_id==army.first&&!unit.fit.empty()){expected.emplace_back(unit.id,army.second==0?topology->attacker_entry_id:topology->defender_entry_id);any=true;}if(!any)return common_failure("MilitarySiegeLifecycleRosterRequired",army.first);}
   auto actual=f.after.unit_nodes;std::sort(expected.begin(),expected.end());std::sort(actual.begin(),actual.end());if(expected!=actual)return common_failure("MilitarySiegeLifecycleRosterMismatch",f.id);
  }else if(f.kind==MilitarySiegeLifecycleKind::advanced){
   checked=cause(c,f,"military_siege_engineering_prepared");if(!checked.ok)return checked;const auto* p=find(engineering.preparations,f.cause_id);if(!p||p->siege_id!=f.siege_id||p->topology_id!=f.topology_id||p->from_tick!=f.before->last_tick||p->to_tick!=f.tick||p->round!=f.before->round)return common_failure("MilitarySiegeEngineeringPreparationRequired",f.id);
  }else if(f.kind==MilitarySiegeLifecycleKind::battle_finished){
   checked=cause(c,f,"military_battle");if(!checked.ok)return checked;const auto* battle=find(m.battle_facts,f.cause_id);const auto* contact=battle?find(m.contact_facts,battle->contact_source_id):nullptr;if(!battle||!battle->final||battle->tick>f.tick||!contact||contact->siege_id!=std::optional<StableId>{f.siege_id})return common_failure("MilitarySiegeLifecycleBattleRequired",f.id);
  }else if(f.kind==MilitarySiegeLifecycleKind::closed){
   checked=cause(c,f,"military_siege_released");if(!checked.ok)return checked;const auto* release=find(m.recovery.siege_releases,f.cause_id);if(!release||release->siege_id!=f.siege_id||release->actor_id!=f.actor_id||release->tick!=f.tick)return common_failure("MilitarySiegeLifecycleCloseSourceRequired",f.id);
  }else if(f.kind==MilitarySiegeLifecycleKind::integrated){
   checked=cause(c,f,"military_integration");if(!checked.ok)return checked;const auto* transfer=find(m.integration_facts,f.cause_id);if(!transfer||transfer->siege_id!=f.siege_id||transfer->tick!=f.tick)return common_failure("MilitarySiegeLifecycleIntegrationRequired",f.id);
  }else if(f.kind==MilitarySiegeLifecycleKind::departed){
   checked=cause(c,f,"military_siege_strategic");if(!checked.ok)return checked;const auto* original=find(state.facts,f.cause_id);if(!original||original->id!=f.previous_fact_id||original->siege_id!=f.siege_id||original->tick!=f.tick||original->actor_id!=f.actor_id||!original->strategic_command||original->strategic_command->kind!="negotiate"||original->strategic_command->terms!="safe_departure")return common_failure("MilitarySiegeLifecycleDepartureSourceRequired",f.id);
   std::vector<StableId> armies,unit_ids;for(const auto& army:f.before->armies)if(army.second==1&&std::find(f.before->withdrawn_army_ids.begin(),f.before->withdrawn_army_ids.end(),army.first)==f.before->withdrawn_army_ids.end())armies.push_back(army.first);std::sort(armies.begin(),armies.end());for(const auto& u:f.before->unit_nodes)unit_ids.push_back(u.first);
   auto roster=phase?military_rosters_before(c,m,cat,unit_ids,f.tick,f.id,*phase,population,population_catalog):military_rosters_before(c,m,cat,unit_ids,f.tick,f.id,population,population_catalog);if(!roster.ok)return {false,{},roster.error};auto expected=f.before->unit_nodes;expected.erase(std::remove_if(expected.begin(),expected.end(),[&](const auto& u){const auto* row=find(roster.value,u.first);return row&&std::find(armies.begin(),armies.end(),row->army_id)!=armies.end();}),expected.end());auto departed=f.before->withdrawn_army_ids;departed.insert(departed.end(),armies.begin(),armies.end());if(expected!=f.after.unit_nodes||departed!=f.after.withdrawn_army_ids)return common_failure("MilitarySiegeLifecycleWithdrawal",f.id);
  }else if(f.kind==MilitarySiegeLifecycleKind::strategic&&f.strategic_command->kind=="withdraw"){
   const auto& army=f.strategic_command->army_id;checked=actual_army_actor(c,m,army,f);if(!checked.ok)return checked;std::vector<StableId> unit_ids;for(const auto& u:f.before->unit_nodes)unit_ids.push_back(u.first);auto roster=phase?military_rosters_before(c,m,cat,unit_ids,f.tick,f.id,*phase,population,population_catalog):military_rosters_before(c,m,cat,unit_ids,f.tick,f.id,population,population_catalog);if(!roster.ok)return {false,{},roster.error};auto expected=f.before->unit_nodes;expected.erase(std::remove_if(expected.begin(),expected.end(),[&](const auto& u){const auto* row=find(roster.value,u.first);return row&&row->army_id==army;}),expected.end());auto departed=f.before->withdrawn_army_ids;departed.push_back(army);if(expected!=f.after.unit_nodes||departed!=f.after.withdrawn_army_ids)return common_failure("MilitarySiegeLifecycleWithdrawal",f.id);
  }else if(f.after.unit_nodes!=f.before->unit_nodes||f.after.withdrawn_army_ids!=f.before->withdrawn_army_ids)return common_failure("MilitarySiegeLifecycleUnexpectedUnit",f.id);
  latest[f.siege_id]=&f;
 }
 for(const auto& siege:m.sieges)if(selected(policy,siege.topology_id)){const auto found=latest.find(siege.id);if(found==latest.end()||!same(found->second->after,capture_military_siege_participation(siege)))return common_failure("MilitarySiegeParticipationCurrentMismatch",siege.id);}
 for(const auto& row:c.state().facts.rows())if(row.second.domain=="military"&&row.second.kind.rfind("military_siege_",0)==0&&row.second.kind!="military_siege_engineering_prepared"&&row.second.kind!="military_siege_released"&&!ids.count(row.first))return common_failure("MilitarySiegeLifecyclePayloadMissing",row.first);
 return common_success();
}
Outcome<MilitarySiegeParticipationObservation> read_military_siege_participation_for_engineering(const CommonStore& c,const MilitarySiegeLifecycleState& state,const MilitarySiegeEngineeringPreparation& p,const DynamicStepInput* phase){auto upper=limit(c,phase);if(!upper.ok)return {false,{},upper.error};if(p.to_tick>upper.value)return {false,{},common_failure("MilitarySiegeLifecyclePhaseMismatch",p.id).error};auto snapshot=phase?military_siege_participation_before(c,state,p.siege_id,p.id,*phase):military_siege_participation_before(c,state,p.siege_id,p.id);if(!snapshot.ok)return {false,{},snapshot.error};if(snapshot.value.phase!="active"||snapshot.value.last_tick!=p.from_tick||snapshot.value.round!=p.round)return {false,{},common_failure("MilitarySiegeEngineeringParticipationRequired",p.id).error};MilitarySiegeParticipationObservation out;out.source_identity=c.state().identity;out.siege_id=p.siege_id;out.topology_id=p.topology_id;out.before_fact_id=p.id;out.observed_tick=p.to_tick;out.round=p.round;for(const auto& u:snapshot.value.unit_nodes)out.unit_ids.push_back(u.first);std::sort(out.unit_ids.begin(),out.unit_ids.end());auto end=position(c,p.id);for(const auto& f:state.facts)if(f.siege_id==p.siege_id){auto at=position(c,f.id);if(!at||!end)return {false,{},common_failure("MilitarySiegeLifecycleFactMissing",f.id).error};if(*at<*end)out.lifecycle_source_ids.push_back(f.id);}return {true,std::move(out),{}};}
}
